-- ============================================================
-- ORLONG STAGE 8D.2C — CONDITIONAL ARCHIVE BLOCKS + LORE GRAPH
-- Performance: list RPC returns summaries only; record bodies are
-- fetched on demand. Block-level card gates and graph links remain
-- server-filtered so locked lore is never sent to the browser.
-- ============================================================

-- Stable block identifiers are generated by the editor and stored
-- inside content_blocks[].id. Legacy blocks remain readable.
create table if not exists public.eden_archive_relations (
 relation_id bigint generated always as identity primary key,
 source_entry_id text not null references public.eden_archive_entries(entry_id) on delete cascade,
 source_block_id text,
 target_entry_id text not null references public.eden_archive_entries(entry_id) on delete cascade,
 target_block_id text,
 relationship_type text not null default 'related_to',
 label text not null default '',
 description text not null default '',
 sort_order integer not null default 0,
 is_bidirectional boolean not null default false,
 created_at timestamptz not null default now(),
 constraint eden_archive_relation_not_self check (
  source_entry_id<>target_entry_id or coalesce(source_block_id,'')<>coalesce(target_block_id,'')
 ),
 constraint eden_archive_relation_type check (relationship_type in
  ('parent','child','sibling','spouse','family','friend','ally','rival','member','leader',
   'part_of','powered_by','related_to','created_by','created','participated_in',
   'happened_during','located_in','custom'))
);
create index if not exists eden_archive_relations_source on public.eden_archive_relations(source_entry_id,source_block_id,sort_order);
create index if not exists eden_archive_relations_target on public.eden_archive_relations(target_entry_id,target_block_id);
create index if not exists reader_card_copies_owner_card_archive on public.reader_card_copies(owner_user_id,card_id);
create index if not exists eden_archive_entry_cards_entry_card on public.eden_archive_entry_cards(entry_id,card_id);
alter table public.eden_archive_relations enable row level security;
revoke all on public.eden_archive_relations from anon,authenticated;

-- Reusable security predicate: entry metadata is only available once
-- the entry's complete card key and chapter gate have been satisfied.
create or replace function public.reader_can_access_eden_archive_entry(p_entry_id text)
returns boolean language sql stable security definer set search_path=public,pg_temp
as $$
 select auth.uid() is not null and exists(
  select 1 from public.eden_archive_entries e
  where e.entry_id=p_entry_id and e.is_published=true
   and exists(select 1 from public.eden_archive_entry_cards ec where ec.entry_id=e.entry_id)
   and not exists(select 1 from public.eden_archive_entry_cards ec
    where ec.entry_id=e.entry_id and not exists(
     select 1 from public.reader_card_copies owned
     where owned.owner_user_id=auth.uid() and owned.card_id=ec.card_id))
   and (e.unlock_chapter_id is null or exists(
    select 1 from public.eden_book_chapters ch
    join public.eden_book_parts part on part.part_id=ch.part_id
    where ch.chapter_id=e.unlock_chapter_id and ch.is_published=true and part.is_published=true
     and ch.released_at is not null and ch.released_at<=now()
     and (ch.required_access_key is null or exists(
      select 1 from public.reader_access_grants g
      where g.user_id=auth.uid() and g.access_key=ch.required_access_key))
   ))
 );
$$;
revoke all on function public.reader_can_access_eden_archive_entry(text) from public,anon,authenticated;
grant execute on function public.reader_can_access_eden_archive_entry(text) to authenticated;

create or replace function public.reader_can_access_eden_archive_block(p_block jsonb)
returns boolean language sql stable security definer set search_path=public,pg_temp
as $$
 select case
  when p_block is null then false
  when not (p_block ? 'requiredCardIds') then true
  when jsonb_typeof(p_block->'requiredCardIds')<>'array' then false
  when jsonb_array_length(p_block->'requiredCardIds')=0 then true
  else (select count(distinct owned.card_id)
   from jsonb_array_elements_text(p_block->'requiredCardIds') req(card_id)
   join public.reader_card_copies owned on owned.owner_user_id=auth.uid() and owned.card_id=req.card_id)
   =jsonb_array_length(p_block->'requiredCardIds')
 end;
$$;
revoke all on function public.reader_can_access_eden_archive_block(jsonb) from public,anon,authenticated;
grant execute on function public.reader_can_access_eden_archive_block(jsonb) to authenticated;

-- Lightweight directory: no full text, galleries or content block JSON.
create or replace function public.get_my_eden_archive_entries()
returns jsonb language sql stable security definer set search_path=public,pg_temp
as $$
 select case when auth.uid() is null then '[]'::jsonb else coalesce((
  select jsonb_agg(jsonb_build_object(
   'id',e.entry_id,'title',e.title,'category',e.category,'summary',e.summary,
   'updatedAt',e.updated_at,
   'requiredCardCount',(select count(*) from public.eden_archive_entry_cards ec where ec.entry_id=e.entry_id),
   'contentBlockCount',(select count(*) from jsonb_array_elements(coalesce(e.content_blocks,'[]'::jsonb)) b
    where public.reader_can_access_eden_archive_block(b))
  ) order by e.sort_order,e.title)
  from public.eden_archive_entries e
  where e.is_published=true and public.reader_can_access_eden_archive_entry(e.entry_id)
 ),'[]'::jsonb) end;
$$;

-- Fetch one record only when opened. Filter every conditional block
-- on the server; requiredCardIds are removed from returned JSON.
create or replace function public.get_my_eden_archive_entry(p_entry_id text)
returns jsonb language plpgsql stable security definer set search_path=public,pg_temp
as $$
declare v_entry public.eden_archive_entries%rowtype; v_blocks jsonb; v_connections jsonb;
begin
 if not public.reader_can_access_eden_archive_entry(p_entry_id) then return null; end if;
 select * into v_entry from public.eden_archive_entries where entry_id=p_entry_id;
 select coalesce(jsonb_agg(b.value-'requiredCardIds' order by b.ordinality),'[]'::jsonb)
 into v_blocks
 from jsonb_array_elements(coalesce(v_entry.content_blocks,'[]'::jsonb)) with ordinality b(value,ordinality)
 where public.reader_can_access_eden_archive_block(b.value);
 with edges as (
  select r.relation_id,r.source_block_id,r.target_entry_id,r.target_block_id,
   r.relationship_type,r.label,r.description,r.is_bidirectional,r.sort_order
  from public.eden_archive_relations r
  where r.source_entry_id=p_entry_id and public.reader_can_access_eden_archive_entry(r.target_entry_id)
  union all
  select r.relation_id,r.target_block_id as source_block_id,r.source_entry_id as target_entry_id,
   r.source_block_id as target_block_id,
   case r.relationship_type when 'parent' then 'child' when 'child' then 'parent'
    when 'created_by' then 'created' when 'created' then 'created_by'
    when 'leader' then 'member' when 'member' then 'leader' else r.relationship_type end,
   r.label,r.description,r.is_bidirectional,r.sort_order
  from public.eden_archive_relations r
  where r.target_entry_id=p_entry_id and r.is_bidirectional=true
   and public.reader_can_access_eden_archive_entry(r.source_entry_id)
 )
 select coalesce(jsonb_agg(jsonb_build_object(
   'id',edge.relation_id,'sourceBlockId',edge.source_block_id,'targetEntryId',edge.target_entry_id,
   'targetBlockId',edge.target_block_id,'targetTitle',target.title,'targetCategory',target.category,
   'relationshipType',edge.relationship_type,'label',edge.label,'description',edge.description,
   'bidirectional',edge.is_bidirectional
  ) order by edge.sort_order,edge.relation_id),'[]'::jsonb)
 into v_connections
 from edges edge
 join public.eden_archive_entries target on target.entry_id=edge.target_entry_id
 where (edge.source_block_id is null or exists(
    select 1 from jsonb_array_elements(v_blocks) b where b->>'id'=edge.source_block_id))
  and (edge.target_block_id is null or exists(
    select 1 from jsonb_array_elements(coalesce(target.content_blocks,'[]'::jsonb)) tb
    where tb->>'id'=edge.target_block_id
     and public.reader_can_access_eden_archive_block(tb)));
 return jsonb_build_object(
  'id',v_entry.entry_id,'title',v_entry.title,'category',v_entry.category,
  'summary',v_entry.summary,'content',v_entry.content,'contentBlocks',v_blocks,
  'connections',v_connections,
  'requiredCards',(select coalesce(jsonb_agg(jsonb_build_object('id',c.card_id,'number',c.card_number,'name',c.name,'artworkUrl',c.artwork_url) order by c.card_number),'[]'::jsonb)
   from public.eden_archive_entry_cards ec join public.card_catalogue c on c.card_id=ec.card_id
   where ec.entry_id=p_entry_id and exists(select 1 from public.reader_card_copies owned
    where owned.owner_user_id=auth.uid() and owned.card_id=c.card_id))
 );
end;
$$;

-- Validate block card keys as part of the existing save operation.
create or replace function public.save_moderator_eden_archive_entry_v2(
 p_entry_id text,p_title text,p_category text,p_summary text,p_content text,
 p_content_blocks jsonb default '[]'::jsonb,
 p_unlock_chapter_id text default null,p_required_card_ids text[] default array[]::text[],
 p_sort_order integer default 0,p_is_published boolean default false
)
returns jsonb language plpgsql security definer set search_path=public,pg_temp
as $$
declare v_entry_id text; v_card_count integer; v_blocks jsonb; v_block jsonb; v_ids text[];
begin
 if not public.is_reader_moderator() then raise exception 'Moderator access required'; end if;
 if p_entry_id is null or p_entry_id !~ '^[a-z0-9-]{1,100}$' then raise exception 'Entry ID must use lowercase letters, numbers and hyphens'; end if;
 if nullif(trim(p_title),'') is null or char_length(trim(p_title))>160 then raise exception 'Enter an entry title of 1–160 characters'; end if;
 if p_category not in ('characters','locations','creatures','organisations','history','technology','events','other') then raise exception 'Choose a valid archive category'; end if;
 if char_length(coalesce(p_summary,''))>500 then raise exception 'Summary must be 500 characters or fewer'; end if;
 if nullif(trim(coalesce(p_content,'')),'') is null and nullif(trim(coalesce(p_summary,'')),'') is null then raise exception 'Add a summary or a content block'; end if;
 if p_unlock_chapter_id is not null and not exists(select 1 from public.eden_book_chapters where chapter_id=p_unlock_chapter_id) then raise exception 'Choose a valid chapter release gate'; end if;
 if p_required_card_ids is null or cardinality(p_required_card_ids)<1 then raise exception 'Connect at least one required card to this entry'; end if;
 v_blocks:=coalesce(p_content_blocks,'[]'::jsonb);
 if jsonb_typeof(v_blocks)<>'array' or octet_length(v_blocks::text)>180000 then raise exception 'Archive blocks must be an array under 180 KB'; end if;
 if exists(select 1 from jsonb_array_elements(v_blocks) b
  where jsonb_typeof(b)<>'object' or coalesce(b->>'type','') not in
  ('text','quote','image','callout','divider','timeline','reveal','facts','gallery','relationship_map')) then
  raise exception 'One or more archive blocks use an unsupported format'; end if;
 if exists(select 1 from jsonb_array_elements(v_blocks) b
  where nullif(b->>'id','') is null) then raise exception 'Every archive block needs a stable block ID'; end if;
 if (select count(*) from jsonb_array_elements(v_blocks) b)
    <>(select count(distinct b->>'id') from jsonb_array_elements(v_blocks) b) then
  raise exception 'Archive block IDs must be unique within an entry'; end if;
 select count(distinct requested.card_id) into v_card_count
 from unnest(p_required_card_ids) requested(card_id)
 join public.card_catalogue c on c.card_id=requested.card_id where c.is_active=true;
 if v_card_count<>cardinality(p_required_card_ids) then raise exception 'One or more selected entry cards are invalid, inactive or duplicated'; end if;
 for v_block in select value from jsonb_array_elements(v_blocks) loop
  if v_block ? 'requiredCardIds' and jsonb_typeof(v_block->'requiredCardIds') not in ('array','null') then
   raise exception 'Block card requirements must be an array of card IDs';
  end if;
  v_ids:=case when jsonb_typeof(v_block->'requiredCardIds')='array'
   then array(select jsonb_array_elements_text(v_block->'requiredCardIds')) else array[]::text[] end;
  if cardinality(v_ids)>0 and (
   select count(distinct c.card_id) from unnest(v_ids) x(card_id)
   join public.card_catalogue c on c.card_id=x.card_id and c.is_active=true
  )<>cardinality(v_ids) then raise exception 'A block has an invalid or duplicated card requirement'; end if;
 end loop;
 insert into public.eden_archive_entries(entry_id,title,category,summary,content,content_blocks,unlock_chapter_id,sort_order,is_published,updated_at)
 values(p_entry_id,trim(p_title),p_category,coalesce(nullif(trim(p_summary),''),trim(p_content)),
  coalesce(nullif(trim(p_content),''),trim(p_summary)),v_blocks,nullif(trim(p_unlock_chapter_id),''),
  coalesce(p_sort_order,0),coalesce(p_is_published,false),now())
 on conflict(entry_id) do update set title=excluded.title,category=excluded.category,summary=excluded.summary,
  content=excluded.content,content_blocks=excluded.content_blocks,unlock_chapter_id=excluded.unlock_chapter_id,
  sort_order=excluded.sort_order,is_published=excluded.is_published,updated_at=now()
 returning entry_id into v_entry_id;
 delete from public.eden_archive_entry_cards where entry_id=v_entry_id;
 insert into public.eden_archive_entry_cards(entry_id,card_id)
 select v_entry_id,requested.card_id from unnest(p_required_card_ids) requested(card_id);
 return jsonb_build_object('success',true,'entry_id',v_entry_id,'required_cards',v_card_count,'blocks',jsonb_array_length(v_blocks));
end;
$$;

create or replace function public.get_moderator_eden_archive_relations()
returns jsonb language plpgsql stable security definer set search_path=public,pg_temp
as $$
begin
 if not public.is_reader_moderator() then raise exception 'Moderator access required'; end if;
 return coalesce((select jsonb_agg(jsonb_build_object(
  'id',r.relation_id,'sourceEntryId',r.source_entry_id,'sourceBlockId',r.source_block_id,
  'targetEntryId',r.target_entry_id,'targetBlockId',r.target_block_id,
  'type',r.relationship_type,'label',r.label,'description',r.description,
  'sortOrder',r.sort_order,'bidirectional',r.is_bidirectional
 ) order by r.source_entry_id,r.sort_order,r.relation_id) from public.eden_archive_relations r),'[]'::jsonb);
end;
$$;

create or replace function public.save_moderator_eden_archive_relation(
 p_relation_id bigint,p_source_entry_id text,p_source_block_id text,
 p_target_entry_id text,p_target_block_id text,p_relationship_type text,
 p_label text,p_description text,p_sort_order integer default 0,
 p_is_bidirectional boolean default false
)
returns jsonb language plpgsql security definer set search_path=public,pg_temp
as $$
declare v_id bigint;
begin
 if not public.is_reader_moderator() then raise exception 'Moderator access required'; end if;
 if not exists(select 1 from public.eden_archive_entries where entry_id=p_source_entry_id)
  or not exists(select 1 from public.eden_archive_entries where entry_id=p_target_entry_id) then
  raise exception 'Choose two existing archive entries'; end if;
 if p_relationship_type not in ('parent','child','sibling','spouse','family','friend','ally','rival','member','leader','part_of','powered_by','related_to','created_by','created','participated_in','happened_during','located_in','custom') then
  raise exception 'Choose a valid relationship type'; end if;
 if p_source_block_id is not null and not exists(select 1 from public.eden_archive_entries e,jsonb_array_elements(e.content_blocks) b
  where e.entry_id=p_source_entry_id and b->>'id'=p_source_block_id) then raise exception 'The source block no longer exists'; end if;
 if p_target_block_id is not null and not exists(select 1 from public.eden_archive_entries e,jsonb_array_elements(e.content_blocks) b
  where e.entry_id=p_target_entry_id and b->>'id'=p_target_block_id) then raise exception 'The target block no longer exists'; end if;
 if p_relation_id is null then
  insert into public.eden_archive_relations(source_entry_id,source_block_id,target_entry_id,target_block_id,relationship_type,label,description,sort_order,is_bidirectional)
  values(p_source_entry_id,nullif(p_source_block_id,''),p_target_entry_id,nullif(p_target_block_id,''),p_relationship_type,
   left(coalesce(p_label,''),120),left(coalesce(p_description,''),500),coalesce(p_sort_order,0),coalesce(p_is_bidirectional,false))
  returning relation_id into v_id;
 else
  update public.eden_archive_relations set source_entry_id=p_source_entry_id,source_block_id=nullif(p_source_block_id,''),
   target_entry_id=p_target_entry_id,target_block_id=nullif(p_target_block_id,''),relationship_type=p_relationship_type,
   label=left(coalesce(p_label,''),120),description=left(coalesce(p_description,''),500),
   sort_order=coalesce(p_sort_order,0),is_bidirectional=coalesce(p_is_bidirectional,false)
  where relation_id=p_relation_id returning relation_id into v_id;
  if v_id is null then raise exception 'Archive connection not found'; end if;
 end if;
 return jsonb_build_object('success',true,'relation_id',v_id);
end;
$$;

create or replace function public.delete_moderator_eden_archive_relation(p_relation_id bigint)
returns jsonb language plpgsql security definer set search_path=public,pg_temp
as $$
begin
 if not public.is_reader_moderator() then raise exception 'Moderator access required'; end if;
 delete from public.eden_archive_relations where relation_id=p_relation_id;
 if not found then raise exception 'Archive connection not found'; end if;
 return jsonb_build_object('success',true,'deleted',p_relation_id);
end;
$$;

revoke all on function public.get_my_eden_archive_entries() from public,anon;
revoke all on function public.get_my_eden_archive_entry(text) from public,anon;
revoke all on function public.reader_can_access_eden_archive_block(jsonb) from public,anon;
revoke all on function public.get_moderator_eden_archive_relations() from public,anon;
revoke all on function public.save_moderator_eden_archive_entry_v2(text,text,text,text,text,jsonb,text,text[],integer,boolean) from public,anon;
revoke all on function public.save_moderator_eden_archive_relation(bigint,text,text,text,text,text,text,text,integer,boolean) from public,anon;
revoke all on function public.delete_moderator_eden_archive_relation(bigint) from public,anon;
grant execute on function public.get_my_eden_archive_entries() to authenticated;
grant execute on function public.get_my_eden_archive_entry(text) to authenticated;
grant execute on function public.reader_can_access_eden_archive_block(jsonb) to authenticated;
grant execute on function public.get_moderator_eden_archive_relations() to authenticated;
grant execute on function public.save_moderator_eden_archive_entry_v2(text,text,text,text,text,jsonb,text,text[],integer,boolean) to authenticated;
grant execute on function public.save_moderator_eden_archive_relation(bigint,text,text,text,text,text,text,text,integer,boolean) to authenticated;
grant execute on function public.delete_moderator_eden_archive_relation(bigint) to authenticated;

select count(*) as total_archive_entries from public.eden_archive_entries;
